mapper.select:
SELECT product_name, code_number, specification, ROUND(price, 2) AS price, MIN(price) AS price_raw, MAX(price) AS price_raw_max,
SUBSTRING_INDEX(GROUP_CONCAT(COALESCE(type, '') ORDER BY price ASC SEPARATOR '|||'), '|||', 1) AS type, COALESCE(SUM(in_quantity), 0) - COALESCE(SUM(out_quantity), 0) AS total_stock, SUM((COALESCE(in_quantity, 0) - COALESCE(out_quantity, 0)) * ROUND(price, 2)) AS total_price FROM ${table}
deleted_at IS NULL
AND target_system = #{targetSystem}
AND date <= #{endDate}
GROUP BY product_name, code_number, specification, ROUND(price, 2) HAVING COALESCE(SUM(in_quantity), 0) - COALESCE(SUM(out_quantity), 0) <> 0 ORDER BY product_name, code_number

SELECT SUM(in_quantity * price) AS total_supply_value
FROM ${table}
WHERE in_quantity > 0
  AND deleted_at IS NULL
  AND date BETWEEN #{start} AND #{end}
